package com.panish.ridebooking.rider.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.panish.ridebooking.events.RideRequestedEvent; import com.panish.ridebooking.rider.api.*; import com.panish.ridebooking.rider.domain.OutboxEvent; import com.panish.ridebooking.rider.repository.OutboxEventRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class RiderService { private final OutboxEventRepository outbox; private final ObjectMapper mapper; public RiderService(OutboxEventRepository outbox,ObjectMapper mapper){this.outbox=outbox;this.mapper=mapper;} @Transactional public RideRequestResponse requestRide(CreateRideRequest request){String id=UUID.randomUUID().toString(); RideRequestedEvent event=new RideRequestedEvent(id,request.riderId(),request.pickup().trim(),request.dropoff().trim()); try{outbox.save(new OutboxEvent(id,"ride-requested-topic",mapper.writeValueAsString(event)));}catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize ride request",e);} return new RideRequestResponse(id,"ACCEPTED","Ride request queued for processing");} }